insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_123'
from (values
('127.865. d.1.A',3,'A practicum intern at a bottling plant is told the filler line keeps stopping. Before suggesting a fix, she lists when it stops, which station is involved and what changed that week. She is:','["analyzing the elements of a problem", "ordering new equipment right away", "ignoring the problem", "assigning blame"]'::jsonb,0,'Break a problem into parts first.','original'),
('127.865. d.1.A',4,'Which step belongs at the start of solving a recurring jam on a packaging line?','["blame the night crew", "define the problem and gather facts about when and where it occurs", "replace every part", "wait for the shift to end"]'::jsonb,1,'Define before fixing.','original'),
('127.865. d.1.B',3,'An intern finds two websites that give different torque values for the same fastener. Checking which one cites the manufacturer''s manual is an example of:','["copying the first result", "trusting the longer page", "judging the value of information critically", "picking the brighter site"]'::jsonb,2,'Critical analysis checks the source.','original'),
('127.865. d.1.B',4,'Which source is most likely to give a trustworthy specification for a machine at the practicum site?','["a rumor from a coworker", "an anonymous forum post", "a social media comment", "the equipment manufacturer''s technical manual"]'::jsonb,3,'Primary technical sources are reliable.','original'),
('127.865. d.1.C',3,'A practicum student reads a supplier datasheet, a safety data sheet and a trade journal article before recommending a coolant. This is:','["technical research to gather information for decision making", "avoiding the decision", "guessing a choice", "delaying the task"]'::jsonb,0,'Research supports decisions.','original'),
('127.865. d.1.C',4,'After collecting research on three coolants, the intern should next:','["discard all the notes", "compare the findings against the plant''s needs before deciding", "ask no one", "pick the cheapest without reading"]'::jsonb,1,'Compare, then decide.','original'),
('127.865. d.2.A',3,'A crew leader admits her own mistake in a setup, thanks the operator who caught it and keeps a calm tone. Which leadership characteristics is she showing?','["favoritism", "anger and pressure", "integrity and a positive attitude that build trust", "secrecy and blame"]'::jsonb,2,'Honesty builds trust.','original'),
('127.865. d.2.A',4,'Team members follow a supervisor who keeps promises and shares credit. This best shows that trust is built through:','["hidden plans", "random decisions", "loud commands", "consistent honest actions"]'::jsonb,3,'Consistency builds trust.','original'),
('127.865. d.2.B',3,'Two interns on a pallet-wrapping task agree who loads, who wraps and who labels, then help each other finish early. This shows:','["teamwork through cooperating to meet a shared goal", "working alone", "competing for credit", "avoiding the task"]'::jsonb,0,'Cooperation achieves goals.','original'),
('127.865. d.2.B',4,'When a teammate is behind on a shared order, the best teamwork response is to:','["start a different job", "offer help so the group goal is still met", "report only the delay", "wait and watch"]'::jsonb,1,'Shared goals need shared effort.','original'),
('127.865. d.2.C',3,'Before a plant meeting ends, the facilitator asks everyone to voice concerns until the group agrees on one plan. This process is called:','["avoiding discussion", "voting by force", "building consensus", "dictating"]'::jsonb,2,'Consensus is group agreement.','original'),
('127.865. d.2.C',4,'A team that holds a short lunch together to welcome a new hire is engaged in:','["payroll processing", "inventory counting", "equipment testing", "team building"]'::jsonb,3,'Team building strengthens relationships.','original'),
('127.865. d.2.D',3,'On a group project, each practicum student completes the section assigned to them and also covers the cleanup rotation. They are demonstrating:','["responsibility for shared group and individual tasks", "avoiding duties", "waiting to be told", "passing blame"]'::jsonb,0,'Own your part.','original'),
('127.865. d.2.D',4,'If an individual task is left undone, the effect on the group is that:','["the group finishes sooner", "the shared result may be delayed or lowered", "nothing changes", "it improves quality"]'::jsonb,1,'Tasks depend on each other.','original'),
('127.865. d.2.E',3,'An intern greets coworkers by name, returns tools promptly and thanks the maintenance crew. This helps to:','["limit cooperation", "create conflict", "establish and maintain effective working relationships", "avoid feedback"]'::jsonb,2,'Respect builds relationships.','original'),
('127.865. d.2.E',4,'Which habit best keeps a working relationship strong after a disagreement over scheduling?','["gossiping about it", "ignoring the person", "refusing to cooperate", "calmly discussing the issue and following through on what was agreed"]'::jsonb,3,'Resolve respectfully.','original'),
('127.865. d.3.A',3,'A student tells the supervisor that the part needs to be chamfered, using the correct technical term instead of saying ''the edge thing.'' This shows:','["using technical vocabulary correctly", "avoiding specifics", "using slang only", "hiding information"]'::jsonb,0,'Precise terms communicate clearly.','original'),
('127.865. d.3.A',4,'Why does using accurate vocabulary such as ''tolerance'' and ''burr'' matter on a shop floor?','["it makes meetings longer", "it prevents misunderstandings that cause errors or injuries", "it replaces measurements", "it avoids reading manuals"]'::jsonb,1,'Clear terms prevent mistakes.','original'),
('127.865. d.3.B',3,'A practicum student asks the toolroom clerk which drill bit size the job calls for, then repeats it back. She is using:','["no skills", "silence", "verbal skills to obtain and convey information", "only written skills"]'::jsonb,2,'Ask and confirm verbally.','original'),
('127.865. d.3.B',4,'When giving a shift handoff verbally, a worker should:','["omit open issues", "rush through it", "whisper to avoid questions", "state key facts clearly and confirm the next worker understood"]'::jsonb,3,'Confirm understanding.','original'),
('127.865. d.3.C',3,'An intern studies a vendor''s website and a printed technical bulletin to learn how to calibrate a sensor. These are:','["informational texts used for an occupation", "fictional novels", "personal letters", "advertisements only"]'::jsonb,0,'Informational texts guide tasks.','original'),
('127.865. d.3.C',4,'Technical materials such as service bulletins are best used for:','["guessing", "finding procedures and specifications needed for the job", "entertainment", "decoration"]'::jsonb,1,'Bulletins hold procedures.','original'),
('127.865. d.3.D',3,'A student checks the author, date and publisher of a web page about welding codes before using it. She is:','["ignoring details", "guessing", "evaluating the reliability of information", "copying blindly"]'::jsonb,2,'Check the author and date.','original'),
('127.865. d.3.D',4,'An outdated web page about a safety standard is risky because:','["all web pages are the same", "outdated pages are always correct", "dates never matter", "the requirements may have changed since it was written"]'::jsonb,3,'Currency matters.','original'),
('127.865. d.3.E',3,'A supervisor crosses her arms and sighs while the intern explains a delay. The intern recognizes this may signal:','["frustration, so he should explain more clearly and respectfully", "no meaning", "pride", "approval"]'::jsonb,0,'Nonverbal cues carry meaning.','original'),
('127.865. d.3.E',4,'An intern who notices a coworker''s confused expression during a training demo should:','["walk away", "pause and check whether the coworker needs the step explained again", "keep talking", "laugh"]'::jsonb,1,'Respond to cues.','original'),
('127.865. d.3.F',3,'During safety training, a student nods, takes notes and asks, ''So the guard stays in place until the lockout tag is applied?'' She is applying:','["ignoring the speaker", "distracted listening", "active listening by clarifying information", "interrupting"]'::jsonb,2,'Clarify to confirm.','original'),
('127.865. d.3.F',4,'Which response shows active listening after a supervisor gives three instructions?','["walking off", "checking your phone", "saying ''whatever''", "repeating the instructions in your own words to confirm them"]'::jsonb,3,'Paraphrase to confirm.','original'),
('127.865. d.3.G',3,'An intern writes a clear incident summary and then explains it orally to the safety committee. She is using:','["academic skills in written and oral communication", "only drawing", "no communication skills", "only guessing"]'::jsonb,0,'Writing and speaking skills transfer to work.','original'),
('127.865. d.3.G',4,'A well-written work order includes:','["jokes", "what was done, which equipment was involved and the date", "only a signature", "random notes"]'::jsonb,1,'Clear records are complete.','original'),
('127.865. d.4.A',3,'A practicum student finds a supplier''s catalog, checks that the part number matches the drawing and shares it with the buyer. She is using information literacy by:','["deleting records", "hiding information", "accessing, evaluating and disseminating information", "guessing numbers"]'::jsonb,2,'Find, check and share information.','original'),
('127.865. d.4.A',4,'Before passing on a spec sheet to the team, an intern should first:','["rewrite it from memory", "keep it private", "print it without reading", "verify that it is the current revision"]'::jsonb,3,'Evaluate before sharing.','original'),
('127.865. d.4.B',3,'A plant stores work orders, inspection logs and inventory counts in one system so the right people can find them. This is:','["information management", "a lunch plan", "a machine part", "a safety sign"]'::jsonb,0,'Organize and control information.','original'),
('127.865. d.4.B',4,'Good information management on a factory floor makes it easier to:','["slow communication", "find accurate records quickly and avoid duplicated work", "hide data", "lose files"]'::jsonb,1,'Organized data saves time.','original'),
('127.865. d.4.C',3,'At the end of each shift, an intern logs units produced, scrap counts and downtime in the plant''s system. This is:','["wasting time", "skipping documentation", "maintaining records to support ongoing operations", "copying a coworker''s lunch order"]'::jsonb,2,'Records help operations.','original'),
('127.865. d.4.C',4,'Why are accurate scrap records important to a manufacturing business?','["they remove the need for planning", "they replace inspections", "they decorate reports", "they show where waste occurs so costs can be reduced"]'::jsonb,3,'Data guides improvement.','original'),
('127.865. d.4.D',3,'A student writes ''run 200 clean parts without a rework by Friday'' on her practicum plan. This is:','["developing a goal", "a complaint", "a safety rule", "avoiding planning"]'::jsonb,0,'Specific measurable goals help.','original'),
('127.865. d.4.D',4,'Which goal is the most specific and measurable?','["work faster sometime", "reduce rework from 6 percent to 3 percent within one month", "try harder", "do better"]'::jsonb,1,'SMART goals include numbers and a time.','original'),
('127.865. d.4.E',3,'An intern with a rush order, a safety walkthrough and routine cleanup lists them in order of urgency and importance. She is:','["ignoring tasks", "doing random tasks", "prioritizing tasks", "delaying all tasks"]'::jsonb,2,'Order by urgency and importance.','original'),
('127.865. d.4.E',4,'Which task should come first on a busy shift?','["rearranging labels", "sorting old paperwork", "organizing a shelf", "fixing a leaking hydraulic hose that creates a slipping hazard"]'::jsonb,3,'Safety hazards come first.','original'),
('127.865. d.4.F',3,'A student estimates two hours for setup, three for production and one for cleanup, then schedules them across the day. She is:','["developing a timeline using time-management skills", "skipping planning", "wasting time", "avoiding a schedule"]'::jsonb,0,'Timelines map tasks to time.','original'),
('127.865. d.4.F',4,'A good timeline for a multi-day practicum project should include:','["only the end date", "start and end dates plus key checkpoints", "only a title", "no dates"]'::jsonb,1,'Checkpoints keep projects on track.','original'),
('127.865. d.4.G',3,'A practicum team defines a project, plans the steps, carries them out, tracks progress and wraps up. These are phases of:','["machine lubrication", "inventory counting", "project management", "safety training"]'::jsonb,2,'Initiate, plan, execute, monitor, close.','original'),
('127.865. d.4.G',4,'In the monitor and control phase of a project, the team should:','["ignore the plan", "stop tracking", "start over without checking", "compare progress with the plan and adjust as needed"]'::jsonb,3,'Monitoring keeps the project on course.','original'),
('127.865. d.4.H',3,'An intern asks her supervisor to watch her set up a CNC fixture and rate her on accuracy and speed. This is:','["evaluating proficiency in technical skills", "skipping practice", "reducing training", "avoiding a task"]'::jsonb,0,'Self and supervisor evaluation of skills.','original'),
('127.865. d.4.H',4,'What is the best use of the results from a skills evaluation?','["hide the weaknesses", "identify strengths and set goals to improve weak areas", "avoid more practice", "ignore the results"]'::jsonb,1,'Use evaluation to grow.','original'),
('127.865. d.4.I',3,'A supervisor tells an intern her weld spacing is uneven. She thanks him, asks for an example and tries again. She is:','["ignoring him", "quitting", "accepting critical feedback professionally", "arguing"]'::jsonb,2,'Receive feedback constructively.','original'),
('127.865. d.4.I',4,'The most productive response to critical feedback from a supervisor is to:','["avoid the supervisor", "blame the equipment", "argue each point", "listen, ask questions and apply the suggestions"]'::jsonb,3,'Feedback is a tool for growth.','original'),
('127.865. d.5.A',3,'After eight weeks, an intern can set up a lathe alone, a task that needed full guidance in week one. This shows:','["growth of technical skill competencies", "a decline in skills", "no change", "a lost task"]'::jsonb,0,'Competence grows with practice.','original'),
('127.865. d.5.A',4,'Which evidence best shows growth in a technical skill during a practicum?','["a coworker''s opinion only", "a series of inspection results that improve over time", "a single lucky result", "a blank sheet"]'::jsonb,1,'Document improvement.','original'),
('127.865. d.5.B',3,'A student earns a forklift certification during her practicum and logs the hours. This shows:','["a scheduling mistake", "avoiding training", "technical knowledge and skills demonstrated through earning a credential", "a class absence"]'::jsonb,2,'Credentials demonstrate skills.','original'),
('127.865. d.5.B',4,'A practicum activity that best demonstrates technical skills is:','["watching a break video", "sorting mail", "reading a poster", "completing a supervised task and being evaluated on it"]'::jsonb,3,'Hands-on evaluated tasks show competence.','original'),
('127.865. d.5.C',3,'At the end of the practicum, a student writes a one-page summary listing the main duties, key skills used and results achieved. This is:','["an abstract of key points of the practicum", "a pay stub", "an invoice", "a work order"]'::jsonb,0,'Abstracts summarize.','original'),
('127.865. d.5.C',4,'A good practicum abstract should be:','["a list of complaints", "brief and focused on the most important points", "unrelated stories", "a long copy of every log"]'::jsonb,1,'Abstracts are concise.','original'),
('127.865. d.5.D',3,'A student lists her machine operation, quality inspection and teamwork experience at the top of a one-page document for employers. This is a:','["shift schedule", "work order", "job-skills resume", "parking permit"]'::jsonb,2,'Resumes highlight skills.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_123'
from (values
('127.865. d.5.D',4,'What should a job-skills resume emphasize for a manufacturing technician position?','["unproven claims", "unrelated hobbies only", "favorite foods", "relevant technical skills, certifications and accomplishments"]'::jsonb,3,'Target the job.','original'),
('127.865. d.5.E',3,'An intern saves a photo of a finished fixture, an inspection report and a signed work order showing her contribution. She is:','["collecting representative work samples", "hiding work", "destroying records", "avoiding reviews"]'::jsonb,0,'Samples show real work.','original'),
('127.865. d.5.E',4,'A work sample from a practicum should be included only after the student:','["discards the original", "checks that it contains no confidential company information", "posts it online first", "adds private data"]'::jsonb,1,'Protect confidentiality.','original'),
('127.865. d.5.F',3,'A student keeps copies of her supervisor''s written reviews and the industrial representative''s feedback form in her binder. She is:','["hiding reviews", "throwing away reviews", "maintaining copies of practicum evaluations", "sharing them with strangers"]'::jsonb,2,'Keep evaluations for the portfolio.','original'),
('127.865. d.5.F',4,'Evaluations from a practicum supervisor are valuable in a portfolio because they:','["are optional decoration", "replace all records", "hide weaknesses", "provide outside evidence of the student''s performance"]'::jsonb,3,'Third-party evidence adds credibility.','original'),
('127.865. d.5.G',3,'At a school event, a student walks a panel of local employers through her portfolio and answers questions. She is:','["presenting the portfolio to interested stakeholders", "avoiding feedback", "skipping a presentation", "hiding work"]'::jsonb,0,'Presenting showcases skills.','original'),
('127.865. d.5.G',4,'When presenting a portfolio to employers, a student should:','["avoid eye contact", "speak clearly, show evidence and be ready to answer questions", "read silently", "skip the evidence"]'::jsonb,1,'Prepare and engage.','original'),
('127.866.d.1.A',3,'An advanced practicum student explains a calibration step to a new hire using short sentences, a gesture to the gauge and a quick demonstration. This is:','["confusing speech", "long rambling", "clear, concise verbal and nonverbal communication", "silent avoidance"]'::jsonb,2,'Clear verbal and nonverbal communication.','original'),
('127.866.d.1.A',4,'Which message is the clearest handoff note for a night shift?','["''Same as always.''", "''Stuff is broken.''", "''You''ll see.''", "''Press 4 is down for a seal leak; parts arrive Tuesday; use Press 5.''"]'::jsonb,3,'Specific, concise and actionable.','original'),
('127.866.d.1.B',3,'A student reviews a week of defect counts, spots that most occur on third shift and reports it with a simple chart. She is:','["analyzing and communicating data effectively", "avoiding charts", "guessing causes", "hiding data"]'::jsonb,0,'Analyze and present data clearly.','original'),
('127.866.d.1.B',4,'When presenting an observation about a machine''s vibration to a supervisor, the student should:','["skip the numbers", "give the measurements, the time they were taken and what changed", "say it feels off", "exaggerate"]'::jsonb,1,'Include facts and context.','original'),
('127.866.d.1.C',3,'A supervisor frowns at a mislabeled box and says nothing. The practicum student correctly reads this as a sign that:','["everything is perfect", "she should ignore it", "something needs correcting and she should ask what is wrong", "she should leave"]'::jsonb,2,'Nonverbal cues carry meaning.','original'),
('127.866.d.1.C',4,'Which behavior best shows reading a coworker''s nonverbal cues?','["talking louder", "ignoring the pause", "walking away", "noticing hesitation and asking whether more explanation is needed"]'::jsonb,3,'Respond to cues.','original'),
('127.866.d.1.D',3,'During a quality briefing, a student makes eye contact, avoids interrupting and summarizes the key points before asking questions. She is applying:','["active listening", "talking over others", "daydreaming", "distracted listening"]'::jsonb,0,'Active listening includes summarizing.','original'),
('127.866.d.1.D',4,'To confirm that she understood a complex work instruction, the student should:','["nod without thinking", "restate the steps and ask whether she has them right", "guess the details", "skip the instruction"]'::jsonb,1,'Clarify to avoid errors.','original'),
('127.866.d.2.A',3,'A student working on a fixture problem tries a plan alone, then tests it with a partner and revises it based on the results. She is employing:','["random guessing", "copying answers", "critical-thinking skills independently and in a group", "avoiding thinking"]'::jsonb,2,'Critical thinking works alone and in teams.','original'),
('127.866.d.2.A',4,'Which habit shows increasing fluency in critical thinking?','["picking the first idea", "following without thinking", "avoiding questions", "weighing evidence and alternatives before choosing a solution"]'::jsonb,3,'Evaluate options with evidence.','original'),
('127.866.d.2.B',3,'A scrap rate keeps climbing on a cutting line. The student separates the causes into material, tool wear and setup, then proposes a new tool-change interval. She is:','["analyzing the elements of a problem to develop an innovative solution", "ignoring the data", "waiting for a failure", "blaming people"]'::jsonb,0,'Break down, then create solutions.','original'),
('127.866.d.2.B',4,'A creative solution to reduce changeover time on a packaging line might be to:','["remove safety steps", "stage tools and parts at the machine before the previous run ends", "slow the previous run", "skip cleaning"]'::jsonb,1,'Prepare during runtime.','original'),
('127.866.d.2.C',3,'Before recommending a new sensor, the student reads the vendor spec, compares two models and interviews the maintenance lead. This is:','["avoiding the decision", "guessing a model", "conducting technical research for a decision", "choosing by color"]'::jsonb,2,'Research informs choices.','original'),
('127.866.d.2.C',4,'Which research source best answers whether a sensor suits a high-heat zone?','["a photo of the sensor", "a catalog price", "a coworker''s guess", "the manufacturer''s temperature rating in the datasheet"]'::jsonb,3,'Specs show limits.','original'),
('127.866.d.3.A',3,'A student reads the posted rule that machine guards stay in place during operation, and she consistently follows it even when no one is watching. She is:','["demonstrating an understanding of and following workplace safety rules", "ignoring policy", "skipping training", "bending the rules"]'::jsonb,0,'Follow rules consistently.','original'),
('127.866.d.3.A',4,'Why should safety rules be followed even when a task seems quick?','["rules waste time", "most injuries occur when shortcuts are taken", "injuries never happen", "only supervisors need them"]'::jsonb,1,'Shortcuts cause incidents.','original'),
('127.866.d.3.B',3,'A student cuts her finger on a burr. She stops, applies first aid, tells her supervisor and completes the incident form. She is following:','["ignoring the form", "hiding the injury", "procedures for reporting and handling accidents", "waiting a week"]'::jsonb,2,'Report promptly.','original'),
('127.866.d.3.B',4,'Why must even minor accidents and near-misses be reported?','["to avoid training", "to save paper", "to assign blame", "reports reveal hazards that can be fixed before someone is seriously hurt"]'::jsonb,3,'Near-miss reporting prevents injuries.','original'),
('127.866.d.4.A',3,'A student arrives on time, follows the supervisor''s instructions on the day''s tasks and finishes them without being reminded. She is demonstrating:','["a positive, productive work ethic", "avoidance", "laziness", "a poor attitude"]'::jsonb,0,'Reliability shows work ethic.','original'),
('127.866.d.4.A',4,'Which behavior best reflects a strong work ethic during a slow shift?','["leaving early", "finding useful tasks such as cleaning and restocking without being asked", "sitting idle", "checking a phone"]'::jsonb,1,'Initiative shows work ethic.','original'),
('127.866.d.4.B',3,'A student sees a coworker pencil-whip an inspection record to save time. She weighs the risk to customers and reports the issue to the supervisor. She is:','["ignoring the facts", "staying silent", "applying ethical reasoning to make a decision", "joining in"]'::jsonb,2,'Ethical reasoning considers consequences.','original'),
('127.866.d.4.B',4,'An ethical decision in a manufacturing job is best made by considering:','["only personal gain", "what others will not see", "what is easiest", "honesty, safety and the effects on others"]'::jsonb,3,'Weigh honesty and impact.','original'),
('127.866.d.4.C',3,'A student follows environmental rules for disposing of used cutting fluid and wears required PPE every time. She is:','["complying with applicable rules, laws and regulations", "avoiding rules", "breaking policy", "skipping PPE"]'::jsonb,0,'Compliance means consistent follow-through.','original'),
('127.866.d.4.C',4,'Failing to follow applicable regulations at a plant may result in:','["a safer workplace", "fines, injuries and loss of the company''s ability to operate", "higher bonuses", "no consequences"]'::jsonb,1,'Noncompliance has consequences.','original'),
('127.866.d.5.A',3,'A student logs the tasks she performed on the supervised line, notes what went well and what to improve and gets a supervisor sign-off. She is:','["skipping evaluation", "hiding her work", "conducting, documenting and evaluating learning activities", "avoiding documentation"]'::jsonb,2,'Do, document, evaluate.','original'),
('127.866.d.5.A',4,'A learning log entry is most useful when it includes:','["jokes", "only the date", "no details", "the task, the result and what she learned"]'::jsonb,3,'Record outcomes and lessons.','original'),
('127.866.d.5.B',3,'Working beside a senior technician, a student learns to read a servo drive display and adjust parameters under supervision. She is:','["developing advanced technical knowledge and skills related to her occupation", "avoiding training", "repeating basics only", "skipping the display"]'::jsonb,0,'Advanced skills develop with guided practice.','original'),
('127.866.d.5.B',4,'Which activity best develops advanced technical skills in a manufacturing practicum?','["repeating the easiest task only", "completing progressively harder tasks with supervisor feedback", "avoiding feedback", "watching only"]'::jsonb,1,'Progress with feedback.','original'),
('127.866.d.5.C',3,'At week 4 a student needed help to set a press brake; at week 12 she does it alone and passes inspection. This shows:','["a decline in skill", "no change", "growth of her technical skill competencies", "a scheduling error"]'::jsonb,2,'Competence grows.','original'),
('127.866.d.5.C',4,'The strongest evidence of competency growth is:','["hearing praise once", "a lucky first try", "a single guess", "repeatable independent performance that meets quality standards"]'::jsonb,3,'Consistent independent results.','original'),
('127.866.d.5.D',3,'A student scores herself high on welding but low on blueprint reading and asks to practice reading prints. She is:','["evaluating strengths and weaknesses in technical skill proficiency", "ignoring her weaknesses", "hiding her scores", "avoiding practice"]'::jsonb,0,'Honest self-evaluation directs growth.','original'),
('127.866.d.5.D',4,'After identifying a weakness in measuring tools, the next best step is to:','["avoid measuring", "set a goal and practice with feedback until it improves", "hide the weakness", "rely on others forever"]'::jsonb,1,'Plan to improve.','original'),
('127.866.d.5.E',3,'A student gathers pictures of finished parts, inspection reports with her initials and her supervisor''s evaluation for her end-of-term review. She is:','["losing records", "discarding evidence", "collecting representative work samples", "hiding results"]'::jsonb,2,'Samples show growth.','original'),
('127.866.d.5.E',4,'Which item makes the most convincing work sample for a machining practicum?','["a rumor", "a blank form", "an unlabeled photo", "an inspected part with its measurement report and a supervisor note"]'::jsonb,3,'Verified evidence is persuasive.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
